"1611 :     private Dfp multiplyFast(final int x) {
1612 :         Dfp result = newInstance(this);
1613 : 
1614 :         /* handle special cases */
1615 :         if (nans != FINITE) {
1616 :             if (isNaN()) {
1617 :                 return this;
1618 :             }
1619 : 
1620 :             if (nans == INFINITE && x != 0) {
1621 :                 result = newInstance(this);
1622 :                 return result;
1623 :             }
1624 : 
1625 :             if (nans == INFINITE && x == 0) {
1626 :                 field.setIEEEFlagsBits(DfpField.FLAG_INVALID);
1627 :                 result = newInstance(getZero());
1628 :                 result.nans = QNAN;
1629 :                 result = dotrap(DfpField.FLAG_INVALID, MULTIPLY_TRAP, newInstance(getZero()), result);
1630 :                 return result;
1631 :             }
1632 :         }
1633 : 
1634 :         /* range check x */
1635 :         if (x < 0 || x >= RADIX) {
1636 :             field.setIEEEFlagsBits(DfpField.FLAG_INVALID);
1637 :             result = newInstance(getZero());
1638 :             result.nans = QNAN;
1639 :             result = dotrap(DfpField.FLAG_INVALID, MULTIPLY_TRAP, result, result);
1640 :             return result;
1641 :         }
1642 : 
1643 :         int rh = 0;
1644 :         for (int i = 0; i < mant.length; i++) {
1645 :             final int r = mant[i] * x + rh;
1646 :             rh = r / RADIX;
1647 :             result.mant[i] = r - rh * RADIX;
1648 :         }
1649 : 
1650 :         int lostdigit = 0;
1651 :         if (rh != 0) {
1652 :             lostdigit = result.mant[0];
1653 :             result.shiftRight();
1654 :             result.mant[mant.length-1] = rh;
1655 :         }
1656 : 
1657 :         if (result.mant[mant.length-1] == 0) { // if result is zero, set exp to zero
1658 :             result.exp = 0;
1659 :         }
1660 : 
1661 :         final int excp = result.round(lostdigit);
1662 :         if (excp != 0) {
1663 :             result = dotrap(excp, MULTIPLY_TRAP, result, result);
1664 :         }
1665 : 
1666 :         return result;
1667 :     }"

